  PCV3 L2: 5′- CCC[AAGCTT]{.ul}CCCGCGTTTTCCCACAACC-3′;
  PCV3 L3: 5′- GGTTGTGGGAAAACGCGGG-3′;
  PCV3 M2: 5′-CGCGCAGCCGCATCCGCACAAGCTT-3′;
  PCV3 Cap *Bam*HI: 5′-CGC[GGATCC]{.ul}ATGAGACACAGAGCTATATTCAGAA-3′;
