\end{picture}
}
\hspace{-110 pt}
\mathfrak{C}{=}\left(\begin{smallmatrix}
\phantom{-}2&{-}1&\phantom{-}0&\phantom{-}0&\phantom{-}0&\dots&\phantom{-}0&\phantom{-}0&\phantom{-}0&\phantom{-}0\\
{-}1&\phantom{-}2&{-}1&\phantom{-}0&\phantom{-}0&\dots&\phantom{-}0&\phantom{-}0&\phantom{-}0&\phantom{-}0\\
\phantom{-}0&{-}1&\phantom{-}2&{-}1&\phantom{-}0&\dots&\phantom{-}0&\phantom{-}0&\phantom{-}0&\phantom{-}0\\[-1ex]
\vdots&\vdots&\vdots&\vdots&\vdots&\ddots&\vdots&\vdots&\vdots&\vdots\\[0.5ex]
\phantom{-}0&\phantom{-}0&\phantom{-}0&\phantom{-}0&\phantom{-}0&\dots&\phantom{-}0&{-}1&\phantom{-}2&{-}1\\
\phantom{-}0&\phantom{-}0&\phantom{-}0&\phantom{-}0&\phantom{-}0&\dots&\phantom{-}0&\phantom{-}0&{-}1&\phantom{-}2
\end{smallmatrix}\right),
\\[2ex]
\mathfrak{C}^{-1}=\frac{1}{n+1}\left(\begin{smallmatrix}
1\cdot n\;    &1\cdot(n-1)\;&1\cdot(n-2)\;&1\cdot(n-3)\;&\dots &1\cdot 3\;   &1\cdot 2\;   &1\cdot 1\\
1\cdot (n-1)\;&2\cdot(n-1)\;&2\cdot(n-2)\;&2\cdot(n-3)\;&\dots &2\cdot 3\;   &2\cdot 2\;   &2\cdot 1\\
1\cdot (n-2)\;&2\cdot(n-2)\;&3\cdot(n-2)\;&3\cdot(n-3)\;&\dots &3\cdot 3\;   &3\cdot 2\;   &3\cdot 1\\
1\cdot (n-3)\;&2\cdot(n-3)\;&3\cdot(n-3)\;&4\cdot(n-3)\;&\dots &4\cdot 3\;   &4\cdot 2\;   &4\cdot 1\\[-1 ex]
\vdots        &\vdots       &\vdots       &\vdots       &\ddots&\vdots       &\vdots       &\vdots\\[0.5ex]
1\cdot 3\;    &2\cdot3\;    &3\cdot3\;    &4\cdot3\;    &\dots &(n-2)\cdot3\;&(n-2)\cdot2\;&(n-2)\cdot 1\\
1\cdot 2\;    &2\cdot2\;    &3\cdot2\;    &4\cdot2\;    &\dots &(n-2)\cdot2\;&(n-1)\cdot2\;&(n-1)\cdot 1\\
1\cdot 1\;    &2\cdot1\;    &3\cdot1\;    &4\cdot1\;    &\dots &(n-2)\cdot1\;&(n-1)\cdot1\;&n\cdot 1\
