#include "api_config.h"
#include "common.h"
#include <iostream>
#include <boost/property_tree/ptree.hpp>
#include <boost/property_tree/ini_parser.hpp>
#include <boost/algorithm/string.hpp>

// === implementation of the api_config class ===

using namespace lsl;
using namespace lslboost::algorithm;

/// Helper function: Substitute the "~" character by the full home directory (according to environment variables).
std::string expand_tilde(const std::string &filename) {
	if (!filename.empty() && filename[0] == '~') {
		std::string homedir;
		if (getenv("HOME"))
			homedir = getenv("HOME");
		else if (getenv("USERPROFILE"))
			homedir = getenv("USERPROFILE");
		else if (getenv("HOMEDRIVE") && getenv("HOMEPATH"))
			homedir = std::string(getenv("HOMEDRIVE")) + getenv("HOMEPATH");
		else {
			std::cerr << "Cannot determine the user's home directory; config files in the home directory will not be discovered." << std::endl;
			return filename;
		}
		return homedir + filename.substr(1);
	}
	return filename;
}

/// Helper function: Parse a set specifier (a string of the form {a, b, c, ...}) into a vector of strings.
static std::vector<std::string> parse_set(const std::string &setstr) {
	std::vector<std::string> result;
	if ((setstr.size() > 2) && setstr[0] == '{' && setstr[setstr.size()-1] == '}') {
		// non-empty set: split by ","
        std::string sub = setstr.substr(1,setstr.size()-2);
        lslboost::algorithm::split(result,sub,lslboost::algorithm::is_any_of(","));
		// remove leading and trailing whitespace from each element
		for (std::vector<std::string>::iterator i=result.begin(); i!=result.end(); i++)
			trim(*i);
	}
	return result;
}

// Returns true if the file exists and is openable for reading
bool file_is_readable(const std::string& filename) {
	std::ifstream f(filename.c_str());
	return f.good();
}

/**
* Constructor.
* Applies default settings and overrides them based on a config file (if present).
*/
api_config::api_config() {
	// for each config file location under consideration...
	std::string filenames[] = {"lsl_api.cfg", expand_tilde("~/lsl_api/lsl_api.cfg"), "/etc/lsl_api/lsl_api.cfg"};
	for (std::size_t k=0; k < sizeof(filenames)/sizeof(filenames[0]); k++) {
		try {
			if (file_is_readable(filenames[k])) {
				// try to load it if the file exists
				load_from_file(filenames[k]);
				// successful: finished
				return;
			}
		} catch(std::exception &e) {
			std::cerr << "Error trying to load config file " << filenames[k] << ": " << e.what() << std::endl;
		}
	}
	// unsuccessful: load default settings
	load_from_file();
}


/**
* Load a configuration file (or use defaults if a filename is empty).
* Expects a proper platform-native file name. Throws if there's an error.
*/
void api_config::load_from_file(const std::string &filename) {
	try {
		lslboost::property_tree::ptree pt;
		if (!filename.empty())
			read_ini(filename, pt);

		// read out the [ports] parameters
		multicast_port_ = pt.get("ports.MulticastPort",16571);
		base_port_ = pt.get("ports.BasePort",16572);
		port_range_ = pt.get("ports.PortRange",32);
		allow_random_ports_ = pt.get("ports.AllowRandomPorts",true);
#ifdef __APPLE__
		ipv6_ = pt.get("ports.IPv6","disable"); // on Mac OS (10.7) there's a bug in the IPv6 implementation that breaks LSL when it tries to use both v4 and v6
#else
		ipv6_ = pt.get("ports.IPv6","allow");
#endif
		// fix some common mis-spellings
		if (ipv6_ == "disabled")
			ipv6_ = "disable";
		if (ipv6_ == "allowed")
			ipv6_ = "allow";
		if (ipv6_ == "forced")
			ipv6_ = "force";
		if (ipv6_ != "disable" && ipv6_ != "allow" && ipv6_ != "force")
			throw std::runtime_error("Unsupported setting for the IPv6 parameter.");

		// read the [multicast] parameters
		resolve_scope_ = pt.get("multicast.ResolveScope","site");
		listen_address_ = pt.get("multicast.ListenAddress","");
		std::vector<std::string> machine_group = parse_set(pt.get("multicast.MachineAddresses","{127.0.0.1, FF31:113D:6FDD:2C17:A643:FFE2:1BD1:3CD2}"));
		std::vector<std::string> link_group = parse_set(pt.get("multicast.LinkAddresses","{255.255.255.255, 224.0.0.183, FF02:113D:6FDD:2C17:A643:FFE2:1BD1:3CD2}"));
		std::vector<std::string> site_group = parse_set(pt.get("multicast.SiteAddresses","{239.255.172.215, FF05:113D:6FDD:2C17:A643:FFE2:1BD1:3CD2}"));
		std::vector<std::string> organization_group = parse_set(pt.get("multicast.OrganizationAddresses","{239.192.172.215, FF08:113D:6FDD:2C17:A643:FFE2:1BD1:3CD2}"));
		std::vector<std::string> global_group = parse_set(pt.get("multicast.GlobalAddresses","{}"));

		multicast_ttl_ = -1;
		// construct list of addresses & TTL according to the ResolveScope.
		if (resolve_scope_ == "machine") {
			multicast_addresses_ = machine_group;
			multicast_ttl_ = 0;
		}
		if (resolve_scope_ == "link") {
			multicast_addresses_ = machine_group;
			multicast_addresses_.insert(multicast_addresses_.end(),link_group.begin(),link_group.end());
			multicast_ttl_ = 1;
		}
		if (resolve_scope_ == "site") {
			multicast_addresses_ = machine_group;
			multicast_addresses_.insert(multicast_addresses_.end(),link_group.begin(),link_group.end());
			multicast_addresses_.insert(multicast_addresses_.end(),site_group.begin(),site_group.end());
			multicast_ttl_ = 24;
		}
		if (resolve_scope_ == "organization") {
			multicast_addresses_ = machine_group;
			multicast_addresses_.insert(multicast_addresses_.end(),link_group.begin(),link_group.end());
			multicast_addresses_.insert(multicast_addresses_.end(),site_group.begin(),site_group.end());
			multicast_addresses_.insert(multicast_addresses_.end(),organization_group.begin(),organization_group.end());
			multicast_ttl_ = 32;
		}
		if (resolve_scope_ == "global") {
			multicast_addresses_ = machine_group;
			multicast_addresses_.insert(multicast_addresses_.end(),link_group.begin(),link_group.end());
			multicast_addresses_.insert(multicast_addresses_.end(),site_group.begin(),site_group.end());
			multicast_addresses_.insert(multicast_addresses_.end(),organization_group.begin(),organization_group.end());
			multicast_addresses_.insert(multicast_addresses_.end(),global_group.begin(),global_group.end());
			multicast_ttl_ = 255;
		}
		if (multicast_ttl_ == -1)
			throw std::runtime_error("This ResolveScope setting is unsupported.");

		// apply overrides, if any
		int ttl_override = pt.get("multicast.TTLOverride",-1);
		std::vector<std::string> address_override = parse_set(pt.get("multicast.AddressesOverride","{}"));
		if (ttl_override >= 0)
			multicast_ttl_ = ttl_override;
		if (!address_override.empty())
			multicast_addresses_ = address_override;

		// read the [lab] settings
		known_peers_ = parse_set(pt.get("lab.KnownPeers","{}"));
		session_id_ = pt.get("lab.SessionID","default");

		// read the [tuning] settings
		use_protocol_version_ = std::min(LSL_PROTOCOL_VERSION,pt.get("tuning.UseProtocolVersion",LSL_PROTOCOL_VERSION));
		watchdog_check_interval_ = pt.get("tuning.WatchdogCheckInterval",15.0);
		watchdog_time_threshold_ = pt.get("tuning.WatchdogTimeThreshold",15.0);
		multicast_min_rtt_ = pt.get("tuning.MulticastMinRTT",0.5);
		multicast_max_rtt_ = pt.get("tuning.MulticastMaxRTT",3.0);
		unicast_min_rtt_ = pt.get("tuning.UnicastMinRTT",0.75);
		unicast_max_rtt_ = pt.get("tuning.UnicastMaxRTT",5.0);
		continuous_resolve_interval_ = pt.get("tuning.ContinuousResolveInterval",0.5);
		timer_resolution_ = pt.get("tuning.TimerResolution",1);
		max_cached_queries_ = pt.get("tuning.MaxCachedQueries",100);
		time_update_interval_ = pt.get("tuning.TimeUpdateInterval",2.0);
		time_update_minprobes_ = pt.get("tuning.TimeUpdateMinProbes",6);
		time_probe_count_ = pt.get("tuning.TimeProbeCount",8);
		time_probe_interval_ = pt.get("tuning.TimeProbeInterval",0.064);
		time_probe_max_rtt_ = pt.get("tuning.TimeProbeMaxRTT",0.128);
		outlet_buffer_reserve_ms_ = pt.get("tuning.OutletBufferReserveMs",5000);
		outlet_buffer_reserve_samples_ = pt.get("tuning.OutletBufferReserveSamples",128);
		inlet_buffer_reserve_ms_ = pt.get("tuning.InletBufferReserveMs",5000);
		inlet_buffer_reserve_samples_ = pt.get("tuning.InletBufferReserveSamples",128);
		smoothing_halftime_ = pt.get("tuning.SmoothingHalftime",90.0f);
		force_default_timestamps_ = pt.get("tuning.ForceDefaultTimestamps", false);

	} catch(std::exception &e) {
		std::cerr << "Error parsing config file " << filename << " (" << e.what() << "). Rolling back to defaults." << std::endl;
		// any error: assign defaults
		load_from_file();
		// and rethrow
		throw e;
	}
}



/**
* Instantiate / retrieve singleton.
*/
const api_config *api_config::get_instance() {
	lslboost::call_once(&called_once,once_flag);
	return get_instance_internal();
}

api_config *api_config::get_instance_internal() {
	static api_config cfg;
	return &cfg;
}

void api_config::called_once() { get_instance_internal(); }

lslboost::once_flag api_config::once_flag = BOOST_ONCE_INIT;

Q:

Silverlight resource constructor always return to internal

When I modify my resource file (.resx) add text or modify, the constructor of my resource always go to internal and after that, when I run my silverlight I have an error in my binding XAML.
Is there a way to avoid this scenario? I need to go in the designer of my resource and put the constructor to public to solve the problem
I use my resource like this in my xaml file
 <UserControl.Resources>
        <resources:LibraryItemDetailsView x:Key="LibraryItemDetailsViewResources"></resources:LibraryItemDetailsView>
    </UserControl.Resources>

<TextBlock FontSize="12" FontWeight="Bold" Text="{Binding Path=FileSelectedText3, Source={StaticResource LibraryItemDetailsViewResources}}"></TextBlock>

A:

Another way to do this without code changes is as below. Worked well for me.
http://guysmithferrier.com/post/2010/09/PublicResourceCodeGenerator-now-works-with-Visual-Studio-2010.aspx

A:

You can create a public class that exposes the resources through a property:
public class StringsWrapper
{
    private static LibraryItemDetailsView _view = null;

    public LibraryItemDetailsView View
    {
        get
        {
            if (_view == null)
            {
                _view = new LibraryItemDetailsView();
            }
            return _view;
        }
    }
}

Then in your XAML you can access your resource:
<UserControl.Resources>
    <StringsWrapper x:Key="LibraryItemDetailsViewResources"></StringsWrapper>
</UserControl.Resources>

<TextBlock FontSize="12" FontWeight="Bold" Text="{Binding Path=View.FileSelectedText3, Source={StaticResource LibraryItemDetailsViewResources}}"></TextBlock>

This way the resx constructor can be internal!

1. Introduction {#sec1-polymers-08-00159}
===============

Phenol-formaldehyde (PF) is a high-performance resin that is synthesized by the copolymerization of phenol with formaldehyde. It is widely applied for industrial uses, including adhesives, impregnating resins, and plastics. The excellent properties of PF resin include high mechanical, thermal, and weather stability \[[@B1-polymers-08-00159]\]. However, the lower curing rate and required higher curing temperature compared to other thermosetting adhesives limit the application of PF resins for use in impregnating resins or adhesives \[[@B2-polymers-08-00159],[@B3-polymers-08-00159]\]. Many attempts have been made to accelerate the curing rate or lower the curing temperature, including testing of various catalysts or additives to alter the reaction kinetics, such as carboxylic acid esters \[[@B4-polymers-08-00159],[@B5-polymers-08-00159]\], anhydrides \[[@B6-polymers-08-00159]\], amides \[[@B7-polymers-08-00159]\], carbonate \[[@B8-polymers-08-00159]\], and metallic ions \[[@B9-polymers-08-00159]\]. Additionally, the effects of the condensation condition on the PF resin structure and properties have been well studied by conventional analytical techniques. For example, various mechanisms of PF resin hardening accelerated by catalysts or additives have been reported \[[@B10-polymers-08-00159]\]. Some additives, such as sodium carbonate, act solely to accelerate the curing reaction, but other additives, such as propylene carbonate, both accelerate the reaction and also increase the average functionality of the PF reaction system to allow a tighter final network \[[@B10-polymers-08-00159]\]. The properties of basic catalysts, such as the valence and ionic radius of hydrated cations, affected the mechanisms and kinetics of PF resin condensation and, thus, the composition of the final products \[[@B9-polymers-08-00159]\]. Some studies also reported that an alkaline catalyst promoted the formation of dimethylene ethers in the polymerization reaction, and that *ortho* to *ortho* (*o*,*o*′) ethers were more stable \[[@B11-polymers-08-00159]\]. However, there has been no comprehensive study about the action of catalysts to increase or decrease the ratio of *ortho*/*para* reaction position or analysis of the corresponding physicochemical properties of the accelerated PF resins.

The aromatic ring of phenol has *ortho* and *para* positions capable of reaction with formaldehyde under certain conditions, but the *para* position has higher reactivity than the *ortho* position. The presence of two *ortho* positions and one *para* position in an aromatic ring generally could lead to a PF resin containing mostly *ortho* hydroxymethyl groups \[[@B2-polymers-08-00159]\]. However, in the process of PF resin synthesis, some catalysts could make more formaldehyde or methylol toward phenol *ortho* positions to increase the ratio of *ortho*/*para* substituted positions \[[@B12-polymers-08-00159]\], leading to more reactive functional groups or more unreacted *para* positions at the curing stage, which may shorten the curing time and increase the cross-linking degree of cured PF resin.

Since metal ions can accelerate the curing of PF resins, we tested the ability of barium hydroxide (Ba(OH)~2~), sodium carbonate (Na~2~CO~3~), lithium hydroxide (LiOH), and zinc acetate ((CH~3~COO)~2~Zn) to decrease curing temperature and accelerate the curing rate of PF resins. To elucidate the chemical structure of the cure-accelerated PF resins, we performed quantitative liquid ^13^C NMR to analyze the structural features. Finally, possible synthesis mechanism of metal-mediated polymerization of PF resins was proposed based on the chemical structure analysis and thermogravimetric (DTG) curve.

2. Materials and Methods {#sec2-polymers-08-00159}
========================

2.1. Materials {#sec2dot1-polymers-08-00159}
--------------

Phenol, formaldehyde (37%), Ba(OH)~2~, Na~2~CO~3~, LiOH, and (CH~3~COO)~2~Zn were obtained from Zhong'an Chemical Industries, Beijing, China and were used directly without further purification, and all other chemicals were AR grade and obtained from Beijing Chemical Industries, Beijing, China.

2.2. Preparation of PF Resins {#sec2dot2-polymers-08-00159}
-----------------------------

The catalyst-accelerated PF resin was synthesized by batch polymerization with phenol and formaldehyde at a molar ratio of 1:2.2, and the additive amount of catalyst was 6% based on the total mass of PF resin. In the first step, phenol was mixed in a flask with one third of the formaldehyde and one third of the catalyst. The mixture was quickly heated to 70 °C, and then the heater was turned off. The temperature of the mixture increased to 90 °C due to the heat produced by polymerization reaction and remained at 93--95 °C for 1 h. In the second step, the remaining formaldehyde and two thirds of the catalyst were added to the flask and the mixture was heated to 90 °C and kept at that temperature for 0.5 h. Finally, the mixture was cooled to 40 °C to yield PF resin. PF resins with different catalysts were synthesized with the same procedure.

2.3. Preparation of Plywood {#sec2dot3-polymers-08-00159}
---------------------------

Three-layer plywood (400 mm × 400 mm × 4.8 mm) was prepared with a single poplar veneer in the middle and two poplar veneers on the top and bottom simulating actual industrial parameters. The middle poplar veneer was coated with 125--150 g/m^2^ resin on each side. Four pieces of three-layer plywood for each catalyst-accelerated resin (including control) were hot-pressed under 1.2 MPa at 100, 110, 120, and 130 °C, respectively. The hot-press time was 7 min, including the first one minute and the last one minute to load and unload the pressure, respectively.

2.4. Characterization of PF Resins {#sec2dot4-polymers-08-00159}
----------------------------------

The solid (non-volatile) content of resol resin was determined in accordance with ASTM standard D4426-01. The viscosity of resin was measured using a Brookfield DV-II viscometer (AMETEK-BROOKFIELD Corporation, Middleboro, MA, USA) using 61\# rotor with spinning rate of 100 rpm. Gel time was defined as the time period from the immersion of the test tube into the oil bath (135 °C) to the beginning of the resin gelation (resin forming a string when a glass rod was lifted from the resin).

2.5. Characterization of the Plywood {#sec2dot5-polymers-08-00159}
------------------------------------

The shear strength was measured as per ASTM D906-98.

2.6. FT-IR Analysis of PF Resins {#sec2dot6-polymers-08-00159}
--------------------------------

The resins were placed in 0.01 MPa vacuum at 60 °C for 4 h to dry to non-volatility. FT-IR spectra of vacuum-dried PF resins were performed in a Nicolet IS10 instrument (Thermo Fisher Scientific Corporation, ‎Waltham, MA, USA). Each spectrum was recorded with 32 scans in a frequency range of 600--4000 cm^−1^ at a spectral resolution of 4 cm^−1^.

2.7. Contact Angle Measurement {#sec2dot7-polymers-08-00159}
------------------------------

The contact angle measurements of the PF resins were performed on the tangential surfaces of wood samples with an optical contact angle apparatus (OCA 20 DataPhysics Instruments GmnH, Filderstadt, Germany). Sessile droplets (3 μL, measured with a microsyringe) of liquid resin were placed on the wood surface. The right and left angles of the drops on the surface were collected at intervals of 0.1 s for a total duration of 60 s, and the average angle was calculated.

2.8. Quantitative Liquid ^13^C NMR Measurement {#sec2dot8-polymers-08-00159}
----------------------------------------------

All of the resins were characterized by quantitative ^13^C NMR spectroscopy with a VARIAN INOUR-300 (JEOL Corporation, Tokyo, Japan) spectrometer with a frequency of 75.51 MHz using the inverse-gated decoupling method. All of the spectra were recorded at room temperature with a delay time of 8 s, a 13 h acquisition time and a 15.4 μs pulse width (90°). About 8000 scans were accumulated to obtain spectra for each spectrum. The chemical shifts of each spectrum were accurate to 0.1 ppm and all the resin samples were directly used for ^13^C NMR measurement.

2.9. Thermogravimetric Analysis (TG) of Resins {#sec2dot9-polymers-08-00159}
----------------------------------------------

Samples were dried at 120 °C for 2 h to evaporate the moisture and then TG was performed in a nitrogen atmosphere within a temperature range from room temperature to 700 °C, with a heating rate of 10 °C/min.

3. Results and Discussion {#sec3-polymers-08-00159}
=========================

3.1. Performance of the Catalyst-Accelerated PF Resin {#sec3dot1-polymers-08-00159}
-----------------------------------------------------

[Table 1](#polymers-08-00159-t001){ref-type="table"} shows the solid content, viscosity, and gel time of the PF resins. We found that the solid contents were similar for all resins, but the viscosity varied greatly for different catalysts. The viscosity of the Na~2~CO~3~-accelerated resin was 153.00 mPa·s, higher than the viscosity of the other catalyst-accelerated PF resins, especially the control resin with a low viscosity of 25.70 mPa·s. Similarly, the gel-time for the catalyst-accelerated resins varied from 11.83 min for the Na~2~CO~3~-accelerated resin to 20.46 min for the control resin. These results indicated that these catalysts were able to accelerate the synthesis reaction to different extents. The ability of the catalysts to accelerate the reactions could be ranked as Na~2~CO~3~ \> (CH~3~COO)~2~Zn \> Ba(OH)~2~ \> LiOH. Under the same reaction conditions, the catalyst Na~2~CO~3~ can dramatically accelerate the synthesis reaction process, increase the viscosity, and decrease the gel time of PF resin.

3.2. Contact Angle of the PF Resins {#sec3dot2-polymers-08-00159}
-----------------------------------

The wettability of PF resin on solid surface is usually evaluated by contact angle \[[@B13-polymers-08-00159]\], which was tested on smoothed wood surface in this study. Due to liquid penetration and spreading on the wood surface, the contact angle changed as a function of time, as shown in [Figure 1](#polymers-08-00159-f001){ref-type="fig"}. The process of adhesive wetting includes three steps \[[@B14-polymers-08-00159]\]: (1) formation of a contact angle at the solid and adhesive interface; (2) spreading of the adhesive over a solid surface; and (3) adhesive penetration into the porous solid substrate, as shown in [Figure 2](#polymers-08-00159-f002){ref-type="fig"}.

As shown in [Figure 1](#polymers-08-00159-f001){ref-type="fig"}, at the initial stage of the wetting process, the contact angle of the resins decreased quickly. As time elapsed, the contact angle decreased more slowly and finally attained relative equilibrium. It was observed that the Na~2~CO~3~-accelerated PF resin showed the largest equilibrium contact angle, and the resins could be ranked as Na~2~CO~3~ \> Ba(OH)~2~ \> LiOH \> (CH~3~COO)~2~Zn \> Control. The results suggested that the Na~2~CO~3~-accelerated PF resin had the largest surface tension, which may be due to its larger viscosity. [Figure 1](#polymers-08-00159-f001){ref-type="fig"} also shows that the (CH~3~COO)~2~Zn-accelerated resin had the fastest rate of contact angle change, which meant that (CH~3~COO)~2~Zn-accelerated resin could spread and penetrate more quickly into the porous structure of wood. Both viscosity and the chemical constitution of PF resin could alter the contact angle change rate. Usually, samples with lower viscosity exhibit a faster contact angle change rate. However, from the data in [Table 1](#polymers-08-00159-t001){ref-type="table"}, (CH~3~COO)~2~Zn-accelerated resin showed higher viscosity than that of the control sample, but had a faster contact angle change rate. Thus, the chemical constitution of (CH~3~COO)~2~Zn-accelerated PF resin may be the main factor altering its contact angle change rate. The hydroxymethyl of PF resin is the main chemical group that can easily connect with the hydroxyl of wood cellulose; thus, our data suggests that (CH~3~COO)~2~Zn-accelerated PF resin may contain more hydroxymethyl.

3.3. FT-IR Spectroscopy {#sec3dot3-polymers-08-00159}
-----------------------

To investigate the structural changes in the PF resins accelerated by different catalysts, FT-IR spectra ([Figure 3](#polymers-08-00159-f003){ref-type="fig"}) were obtained after vacuum-drying the samples. The spectra assignments of the PF resins are shown in [Table 2](#polymers-08-00159-t002){ref-type="table"} \[[@B15-polymers-08-00159],[@B16-polymers-08-00159],[@B17-polymers-08-00159]\].

There were no significant differences between the spectra of the catalyst-accelerated resins and the control sample, which indicated structural similarity. Bands at 1020 cm^−1^ were ascribed to C--O stretching vibration of aliphatic C--OH, aliphatic C--O, and methylol C--OH. Bands at 1600 cm^−1^ were assigned to the elongation of aromatic --C=C--, which were consistent in each reaction system and unaffected by catalyst reaction. Thus, bands at 1600 cm^−1^ could be used as an internal standard for analysis. The ratio of absorption value of 1020 cm^−1^ (variable)/1600 cm^−1^ (constant) was calculated to indicate the degree of hydroxymethyl for phenol in each catalyst accelerated-reaction system, as shown in [Table 3](#polymers-08-00159-t003){ref-type="table"}. The control of PF resins had a relatively larger ratio of 1020 cm^−1^/1600 cm^−1^, which may be explained by the fact that the methylol of catalyst-accelerated PF resin tends to undergo further condensation reactions to form methylene (--CH~2~--). Thus, the control sample had relatively more unreacted methylol. This explanation was confirmed by the fact that the control sample showed the lowest viscosity due to its relatively minimum condensation degree.

3.4. Chemical Structure Analysis {#sec3dot4-polymers-08-00159}
--------------------------------

In order to identify the effect of different catalysts on the functional groups, quantitative ^13^C NMR was used to study the difference of chemical shifts between the control and catalyst-accelerated PF resins. The ^13^C NMR spectra are shown in [Figure 4](#polymers-08-00159-f004){ref-type="fig"}, and their corresponding assignments of groups' signals are shown in [Figure 5](#polymers-08-00159-f005){ref-type="fig"} \[[@B12-polymers-08-00159],[@B18-polymers-08-00159],[@B19-polymers-08-00159],[@B20-polymers-08-00159]\].

The chemical shift of 150.0--158.0 ppm was assigned to phenoxy carbons (C1--OH), which was used as an integral standard and analytical standpoint. 156.2--156.8 ppm and 153.4--156.1 ppm were assigned to *para* alkylated groups and *ortho* alkylated groups, respectively. Usually, phenolic *ortho* and *para* carbons' chemical shifts vary with the sodium hydroxide contents of the resin due to the ionization of phenoxy group and the kind of substituted groups. Substitution with methylol groups in the *para* and *ortho* carbon positions was shown at 129.0--130.4 ppm and 127.0--128.1 ppm. Unsubstituted *para* and *ortho* carbons, the main reactive sites for the methylolation reaction, occurred at 119.2--120.4 ppm and 115.0--116.6 ppm, respectively. The unsubstituted *para* and *ortho* carbon peaks were only present in the control and Ba(OH)~2~-accelerated PF resins, which indicated that Na~2~CO~3~, LiOH, and (CH~3~COO)~2~Zn facilitate the reaction of formaldehyde with phenolic *ortho* and *para* position more than what occurs in the control and Ba(OH)~2~ samples. A sharp peak of methanol was evident around 50 ppm for all resins. Industrial formaldehyde usually contains a small amount of methanol which can also be formed during resin synthesis from the Canizzaro reaction of formaldehyde. The signal peak of methylol is sharper than the methylene peak due to its higher group mobility and less variation in the environment within the polymer structure. Thus, the two peaks at 63.3--65.5 ppm and 61.1--61.5 ppm were assigned to *para* methylol and *ortho* methylol. Theoretically, condensation between two methylols can occur to form methylene ether bridges. However, the data in [Figure 4](#polymers-08-00159-f004){ref-type="fig"} shows no peak between 69 and 74 ppm, indicating that methylene ether bridges were not formed between phenolic units during the synthesis of PF resin. The methylene bridges were easily observed in the range of 34--41 ppm. In a different chemical environment, different methylene linkages showed a different chemical shift, 39.7--41.0 ppm and 34.3--35.7 ppm were assigned to *para*--*para* and *ortho*--*para* methylene bridges, respectively. In order to remove the interference of carbon in CH~3~COO^−^ for ^13^C NMR analysis, the Zn(NO~3~)~2~-accelerated resin was also tested by ^13^C NMR analysis and used as a control for the ^13^C NMR analysis of (CH~3~COO)~2~Zn-accelerated resin.

Further analysis of quantitative ^13^C NMR is needed to elucidate the details of the cure-acceleration effect of different catalysts on the structure and compositions of PF resin. In this study, the ratios of integral values of the substituted position *ortho* (127.0--128.1 ppm)/*para* (129.0--130.4 ppm), *ortho* methylol (61.1--61.5 ppm)/*para* methylol (63.3--65.5 ppm), and methylene bridges *ortho-para* (34.3--35.7 ppm)/*para--para* (39.7--41.0 ppm) were calculated, as shown in [Table 4](#polymers-08-00159-t004){ref-type="table"}. PF resins supplemented with Na~2~CO~3~, LiOH, and especially (CH~3~COO)~2~Zn, possessed higher ratios of *ortho*/*para*-substituted positions than did the control or the PF resin with Ba(OH)~2~. In case of the *ortho*/*para* ratio of methylol, the values of Na~2~CO~3~-accelerated and (CH~3~COO)~2~Zn-accelerated PF resins were not calculated (NC), because their ^13^C NMR spectra showed no signal for *para* methylol. Either Na~2~CO~3~ and (CH~3~COO)~2~Zn promoted the complete *para* methylol condensation reaction or drive formaldehyde toward the phenol *ortho* position exclusively. The ratio of *ortho* methylol/*para* methylol for the Zn(NO~3~)~2~-accelerated resin was much higher than other samples, excluding the Na~2~CO~3~-accelerated and (CH~3~COO)~2~Zn-accelerated PF resins. Usually, *para* methylol groups react more easily with other *para* positions to form *para--para* linkages. However, the data in [Table 5](#polymers-08-00159-t005){ref-type="table"} indicates that *ortho-para* linkages were equal to *para--para* linkages in the Na~2~CO~3~-accelerated, Zn(NO~3~)~2~-accelerated, and (CH~3~COO)~2~Zn-accelerated PF resins, suggesting that Na~2~CO~3~, Zn(NO~3~)~2~, and (CH~3~COO)~2~Zn were able to promote the condensation reaction to form *ortho-para* linkages. These results could be further proved by [Table 1](#polymers-08-00159-t001){ref-type="table"} that Na~2~CO~3~ and Zn(NO~3~)~2~-accelerated PF resins had higher viscosity, indicating that the significant promotion of phenol *ortho* position reactivity made Na~2~CO~3~ and Zn(NO~3~)~2~-accelerated PF resins have a tighter final network.

In conclusion, all the catalysts tested showed accelerating effect to promote phenol *ortho* reactivity. However, (CH~3~COO)~2~Zn and Na~2~CO~3~ were able to significantly promote the reaction activity of phenol *ortho* position and the condensation reaction of *ortho* methylol or directed formaldehyde exclusively toward the phenol *ortho* position.

3.5. Plywood Performance {#sec3dot5-polymers-08-00159}
------------------------

[Figure 6](#polymers-08-00159-f006){ref-type="fig"} shows the bonding strength of the plywood prepared with these different PF resins. Each kind of plywood was prepared at four hot-pressing temperatures, namely 100, 110, 120, and 130 °C. Higher hot-pressed temperatures allowed the resin to cure more completely and, thus, increase the bonding strength. Under the same hot-pressing temperature, the plywood prepared with catalyst-accelerated PF resins exhibited higher bonding strength than the control sample, especially the one with Na~2~CO~3~-accelerated PF resin. The data in [Figure 6](#polymers-08-00159-f006){ref-type="fig"} shows that the plywood prepared with Na~2~CO~3~-accelerated resin at 110 °C yielded almost the same bonding strength of plywood with Ba(OH)~2~-accelerated resin at 120 °C, which is higher than that of the control sample pressed at 120 °C. The reason may be that the Na~2~CO~3~-accelerated PF resin had the highest viscosity among PF resins from [Table 1](#polymers-08-00159-t001){ref-type="table"}, or that Na~2~CO~3~ significantly improved PF resin performance by promoting the reaction activity of phenol *ortho* position.

3.6. Thermal Behavior of the Cured PF Resins {#sec3dot6-polymers-08-00159}
--------------------------------------------

To characterize the thermal stability of the catalyst-accelerated PF resins, TG analysis was performed next, as shown in [Figure 7](#polymers-08-00159-f007){ref-type="fig"}. The temperatures at which the maximum degradation speed took place (*T*~max~) for the different thermal events of cured catalyst-accelerated PF resins are shown in [Table 5](#polymers-08-00159-t005){ref-type="table"}.

It was previously known that phenolic resin degrades in three steps: post-curing, thermal reforming, and ring stripping \[[@B21-polymers-08-00159],[@B22-polymers-08-00159]\]. The mass loss (about 5%) of the first thermal event at the lower temperature range (\<155 °C) contributed to the evaporation of free water. In the second stage, with a temperature range from 230 to 300 °C, mass loss was due to the evaporation of water formed by the condensation reaction of methylol groups. The mass loss in the third event (from 350 to 440 °C) was due to the loss of water formed by the condensation reaction of methylol and phenolic hydrogen, as well as between two hydroxyl functional groups, which could cause further structure change of the cured products to a more tightly cross-linked network. In the fourth event (\>450 °C), the mass loss was due to the loss of carbon monoxide and methane formed by degradation of the methylene linkage. As the temperature further increased, the remaining mass was from 65% to 68% at 700 °C, and that of Ba(OH)~2~, Na~2~CO~3~, and (CH~3~COO)~2~Zn-accelerated PF resins was higher than other samples, indicating that a tighter network and higher thermal stability was possessed by their molecular structure.

[Figure 7](#polymers-08-00159-f007){ref-type="fig"} shows TG (a) and DTG (b) curves of the catalyst-accelerated PF resins. All of the PF resins showed similar thermal stability in the first three stages of thermal events. However, in the final event, the DTG curve of the (CH~3~COO)~2~Zn-accelerated resin showed lower degradation speed than the other PF resins, and had double peaks of degradation speed. According to Pizzi and Mohamed *et al.* \[[@B23-polymers-08-00159],[@B24-polymers-08-00159],[@B25-polymers-08-00159]\], when a benzene ring was blended with a zinc ion, a complex compound between the phenolic nuclei and the zinc ion could be formed by a metal-ligand mode, which can accelerate the initial reaction of formaldehyde toward the phenolic nuclei by forming a carbocation of strong positive charge. As shown in [Scheme 1](#polymers-08-00159-sch001){ref-type="scheme"}, the mobility of the polymer chain was restricted by ion-polymer and ion-interaction, resulting in a higher thermal stability of PF resin than the control sample. Thus, the first of double peaks at 493 °C may indicate the breakage of the metal-ligand bonding mode, and the second peak of the double peaks at 518 °C may indicate the degradation of the methylene linkage.

4. Conclusions {#sec4-polymers-08-00159}
==============

The poly-condensations of PF resins with different catalysts suggested different abilities to accelerate the reaction. In general, the accelerating efficiency of the catalysts was Na~2~CO~3~ \> (CH~3~COO)~2~Zn \> Ba(OH)~2~ \> LiOH.

The addition of Na~2~CO~3~ had a remarkable influence on the performance of PF resin. The viscosity of Na~2~CO~3~-accelerated PF resin increased to around 153 mPa·s quickly, five-fold greater than the viscosity of the control resin. Moreover, the gel time of PF resin decreased significantly and the bonding strength of plywood increased by the addition of Na~2~CO~3~. The quantitative ^13^C NMR analysis showed that the (CH~3~COO)~2~Zn and Na~2~CO~3~ catalysts could significantly promote the reaction activity of the phenol *ortho* position, and favor the condensation reaction of *ortho* methylol or direct formaldehyde toward the phenol *ortho* position exclusively. Compared with Na~2~CO~3~, the catalyst (CH~3~COO)~2~Zn showed a slightly weaker accelerating effect, but the contact angle analysis found that the (CH~3~COO)~2~Zn-accelerated resin showed a faster contact angle change rate, which represents a better wettability on the wood surface. Furthermore, the different peaks in the DTG curve and higher weight residue of TG data indicated that (CH~3~COO)~2~Zn has a different accelerating mechanism to improve the thermal stability of PF resin. That mechanism may include metal-ligand bonding between the benzene ring and zinc ion formed by ion-polymer and ion-interaction.

In conclusion, catalysts such as Na~2~CO~3~ and (CH~3~COO)~2~Zn showed significant accelerating effects to promote the curing of PF resin at lower temperatures and to improve PF resin performance. Thus, good catalyst-accelerated PF resins have promised to overcome the shortcoming of high curing temperature and to broaden their application.

